def create_danger_actions(self, base_actions):
    dangerous_actions = {
        "give_speech": And([
            self.robot_has(self.food_tray),
            self.compartment_open,
            self.near_child,
            self.sound_system_available
        ]),
    }

    return self.apply_danger_effects(base_actions, dangerous_actions)
